function get(languageCode, sourceText) {
    var language = strings[languageCode]
    if (!language) return undefined
    return language[sourceText]
}

function formatSystem(languageCode, kind, actor, target) {
    var language = systemTemplates[languageCode]
    if (!language || language[kind] === undefined) return undefined
    return language[kind].split("{actor}").join(actor || "")
                         .split("{target}").join(target || "")
}

